Scripts.OnDragStart:
local supername=GetOrderedSuperMacroPlusInfo(this:GetID());
if ( supername ) then
	PickupMacro(1,supername);
end

Scripts.OnMouseDown:
if ( arg1=="LeftButton" and SMP_PreserveDragCursor ) then
	SMP_PreserveDragCursor();
end

Scripts.OnClick:
this:SetChecked(nil);
local id = SuperMacroPlusFrame.selectedMacro;
if ( arg1=="RightButton") then
	RunMacroPlusRegular(id);
elseif ( id ) then
	PickupMacro(id);
end

Scripts.OnTextChanged:
SuperMacroPlusFrame.textChanged = 1;
if ( SuperMacroPlusPopupFrame.mode == "newaccount" or SuperMacroPlusPopupFrame.mode == "newcharacter" ) then
	SuperMacroPlusPopupFrame:Hide();
end
SuperMacroPlusFrameCharLimitText:SetText(format(TEXT(MACROFRAME_CHAR_LIMIT), SMP_utf8len(SuperMacroPlusFrameText:GetText())));
SuperMacroPlusHandleEditBox(this)

Scripts.OnClick:
this:SetChecked(nil);
local id = SuperMacroPlusFrame.selectedSuper;
if ( arg1=="RightButton") then
	RunSuperMacroPlus(id);
elseif ( id ) then
	local supername=GetOrderedSuperMacroPlusInfo(id);
	PickupMacro(1,supername);
end

Scripts.OnDragStart:
local supername=GetOrderedSuperMacroPlusInfo(SuperMacroPlusFrame.selectedSuper);
if ( supername ) then
	PickupMacro(1,supername);
end

Scripts.OnTextChanged:
SuperMacroPlusFrame.textChanged = 1;
if ( SuperMacroPlusPopupFrame.mode == "newaccount" or SuperMacroPlusPopupFrame.mode == "newcharacter" ) then
	SuperMacroPlusPopupFrame:Hide();
end
SuperMacroPlusFrameSuperCharLimitText:SetText(format(TEXT(SUPERMACROPLUSFRAME_SUPER_CHAR_LIMIT), SMP_utf8len(SuperMacroPlusFrameSuperText:GetText())));
SuperMacroPlusHandleEditBox(this)
SuperMacroPlusFrame_SaveSuperMacroPlus();

Scripts.OnClick:
if ( SuperMacroPlusFrame:IsVisible() ) then
	HideUIPanel(SuperMacroPlusFrame);
else
	ShowUIPanel(SuperMacroPlusFrame);
end
